import unittest

from Lab3 import gen_bin_tree

class TestIndex(unittest.TestCase):
    def test_po_umolch(self):
        self.assertEqual(gen_bin_tree(), {'5': [{'25': [{'625': [{'390625': [{'152587890625': [{'23283064365386962890625': []}, {'152587890623': []}]}, {'390623': [{'152586328129': []}, {'390621': []}]}]}, {'623': [{'388129': [{'150644120641': []}, {'388127': []}]}, {'621': [{'385641': []}, {'619': []}]}]}]}, {'23': [{'529': [{'279841': [{'78310985281': []}, {'279839': []}]}, {'527': [{'277729': []}, {'525': []}]}]}, {'21': [{'441': [{'194481': []}, {'439': []}]}, {'19': [{'361': []}, {'17': []}]}]}]}]}, {'3': [{'9': [{'81': [{'6561': [{'43046721': []}, {'6559': []}]}, {'79': [{'6241': []}, {'77': []}]}]}, {'7': [{'49': [{'2401': []}, {'47': []}]}, {'5': [{'25': []}, {'3': []}]}]}]}, {'1': [{'1': [{'1': [{'1': []}, {'-1': []}]}, {'-1': [{'1': []}, {'-3': []}]}]}, {'-1': [{'1': [{'1': []}, {'-1': []}]}, {'-3': [{'9': []}, {'-5': []}]}]}]}]}]})

    def test_one_six(self):
        self.assertEqual(gen_bin_tree(5, 1), {'5': []})
        self.assertEqual(gen_bin_tree(5, 2), {'5': [{'25': []}, {'3': []}]})
        self.assertEqual(gen_bin_tree(5, 3), {'5': [{'25': [{'625': []}, {'23': []}]}, {'3': [{'9': []}, {'1': []}]}]})
        self.assertEqual(gen_bin_tree(5, 4), {'5': [{'25': [{'625': [{'390625': []}, {'623': []}]}, {'23': [{'529': []}, {'21': []}]}]}, {'3': [{'9': [{'81': []}, {'7': []}]}, {'1': [{'1': []}, {'-1': []}]}]}]})
        self.assertEqual(gen_bin_tree(5, 5), {'5': [{'25': [{'625': [{'390625': [{'152587890625': []}, {'390623': []}]}, {'623': [{'388129': []}, {'621': []}]}]}, {'23': [{'529': [{'279841': []}, {'527': []}]}, {'21': [{'441': []}, {'19': []}]}]}]}, {'3': [{'9': [{'81': [{'6561': []}, {'79': []}]}, {'7': [{'49': []}, {'5': []}]}]}, {'1': [{'1': [{'1': []}, {'-1': []}]}, {'-1': [{'1': []}, {'-3': []}]}]}]}]})

if __name__ == '__main__':
    unittest.main()